import React, { useState } from 'react';
import './Register.css';

function Register({ allerVers }) {
  const [etape, setEtape] = useState(1);
  const [prenom, setPrenom] = useState('');
  const [telephone, setTelephone] = useState('');
  const [motDePasse, setMotDePasse] = useState('');
  const [confirmationMotDePasse, setConfirmationMotDePasse] = useState('');
  const [pin, setPin] = useState('');
  const [confirmationPin, setConfirmationPin] = useState('');
  const [role, setRole] = useState('acheteur');
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);

  const handleEtape1 = () => {
    setMessage('');
    if (!prenom || !telephone || !motDePasse || !confirmationMotDePasse) {
      setMessage('❌ Remplissez tous les champs !');
      return;
    }
    if (motDePasse !== confirmationMotDePasse) {
      setMessage('❌ Les mots de passe ne correspondent pas !');
      return;
    }
    if (motDePasse.length < 6) {
      setMessage('❌ Le mot de passe doit contenir au moins 6 caractères !');
      return;
    }
    setEtape(2);
  };

  const handleEtape2 = () => {
    setMessage('');
    if (!/^\d{4}$/.test(pin)) {
      setMessage('❌ Le PIN doit contenir exactement 4 chiffres !');
      return;
    }
    if (pin !== confirmationPin) {
      setMessage('❌ Les codes PIN ne correspondent pas !');
      return;
    }
    handleInscription();
  };

  const handleInscription = async () => {
    setChargement(true);
    try {
      const reponse = await fetch('/api/auth/inscription', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prenom,
          telephone,
          mot_de_passe: motDePasse,
          confirmation_mot_de_passe: confirmationMotDePasse,
          pin,
          role
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        setMessage('✅ ' + donnees.message);
        setTimeout(() => allerVers('login'), 2000);
      } else {
        setMessage('❌ ' + donnees.message);
      }
    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }
    setChargement(false);
  };

  return (
    <div className="register-page">
      <div className="register-box">
        <h1 className="register-logo">🎵 Varim Music</h1>

        {etape === 1 && (
          <>
            <h2 className="register-titre">Créer un compte</h2>
            <p className="register-sous-titre">Rejoignez la communauté musicale africaine</p>

            {message && <div className="register-message">{message}</div>}

            <div className="register-champ">
              <label>Prénom</label>
              <input
                type="text"
                placeholder="Votre prénom"
                value={prenom}
                onChange={(e) => setPrenom(e.target.value)}
              />
            </div>

            <div className="register-champ">
              <label>Numéro de téléphone</label>
              <input
                type="tel"
                placeholder="Ex: 06 123 45 67"
                value={telephone}
                onChange={(e) => setTelephone(e.target.value)}
              />
            </div>

            <div className="register-champ">
              <label>Je suis un</label>
              <div className="register-roles">
                <div
                  className={`role-carte ${role === 'acheteur' ? 'active' : ''}`}
                  onClick={() => setRole('acheteur')}
                >
                  🎧 Acheteur
                </div>
                <div
                  className={`role-carte ${role === 'artiste' ? 'active' : ''}`}
                  onClick={() => setRole('artiste')}
                >
                  🎤 Artiste
                </div>
              </div>
            </div>

            <div className="register-champ">
              <label>Mot de passe</label>
              <input
                type="password"
                placeholder="Minimum 6 caractères"
                value={motDePasse}
                onChange={(e) => setMotDePasse(e.target.value)}
              />
            </div>

            <div className="register-champ">
              <label>Confirmer le mot de passe</label>
              <input
                type="password"
                placeholder="Répétez votre mot de passe"
                value={confirmationMotDePasse}
                onChange={(e) => setConfirmationMotDePasse(e.target.value)}
              />
            </div>

            <button className="register-btn" onClick={handleEtape1}>
              Continuer →
            </button>

            <p className="register-lien">
              Déjà un compte ? <a href="#" onClick={() => allerVers('login')}>Se connecter</a>
            </p>
          </>
        )}

        {etape === 2 && (
          <>
            <h2 className="register-titre">Créer votre code PIN</h2>
            <p className="register-sous-titre">Ce code protège votre compte et vos gains</p>

            <div className="pin-avertissement">
              ⚠️ <strong>Important !</strong> Votre code PIN est confidentiel. Il vous sera demandé pour accéder à votre dashboard et retirer vos gains. Ne le communiquez à personne et ne l'oubliez pas !
            </div>

            {message && <div className="register-message">{message}</div>}

            <div className="register-champ">
              <label>Code PIN (4 chiffres)</label>
              <input
                type="password"
                placeholder="••••"
                maxLength={4}
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                className="pin-input"
              />
            </div>

            <div className="register-champ">
              <label>Confirmer le code PIN</label>
              <input
                type="password"
                placeholder="••••"
                maxLength={4}
                value={confirmationPin}
                onChange={(e) => setConfirmationPin(e.target.value)}
                className="pin-input"
              />
            </div>

            <button
              className="register-btn"
              onClick={handleEtape2}
              disabled={chargement}
            >
              {chargement ? 'Création en cours...' : 'Créer mon compte'}
            </button>

            <p className="register-lien">
              <a href="#" onClick={() => setEtape(1)}>← Retour</a>
            </p>
          </>
        )}
      </div>
    </div>
  );
}

export default Register;
